using System;using System.IO;using System.Text;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using Frociart;
public static class FpgtIntegrationUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Pump(int ms=60){DateTime until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(3);}}static void Until(Func<bool> ready,string why){DateTime until=DateTime.UtcNow.AddSeconds(12);while(!ready()&&DateTime.UtcNow<until)Pump();Check(ready(),why);}
 static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(Control item in All(child))yield return item;}
 static void Capture(Form form,string path){Pump(200);using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
 static string log;static void Phase(string text){File.AppendAllText(log,text+"\n");}
 static void Profile(Action<SourceCodeDialog.TypeProfileDialog> action,Action show){Exception failure=null;bool done=false;DateTime deadline=DateTime.UtcNow.AddSeconds(12);using(var timer=new System.Windows.Forms.Timer{Interval=25}){timer.Tick+=delegate{var form=Application.OpenForms.OfType<SourceCodeDialog.TypeProfileDialog>().FirstOrDefault(f=>f.Visible);if(form==null){if(DateTime.UtcNow>deadline){timer.Stop();Phase("Picker timeout: "+String.Join(", ",Application.OpenForms.Cast<Form>().Select(f=>f.GetType().Name+":"+f.Visible)));foreach(Form f in Application.OpenForms.Cast<Form>().ToList())f.Dispose();failure=new Exception("No profile picker appeared");}return;}timer.Stop();Phase("Picker visible");try{action(form);done=true;Phase("Picker action returned");}catch(Exception error){Phase(error.ToString());failure=error;form.Dispose();}};timer.Start();Phase("Calling show");show();Phase("Show returned");while(!done&&failure==null&&DateTime.UtcNow<deadline)Pump();timer.Stop();}if(failure!=null)throw failure;Check(done,"Native profile action completed");}
 [STAThread]public static int Main(string[] args){try{
  string root=args[0];Directory.CreateDirectory(Path.Combine(root,"ui-fpgt"));log=Path.Combine(root,"ui-fpgt/phase.txt");File.WriteAllText(log,"START\n");Application.EnableVisualStyles();UiMotion.SetEnabled(true);var doc=FlowPseudocode.Decode("LEGGI x\nSTAMPA x+1");string before=Convert.ToBase64String(DiagramIO.EncodeDocument(doc));var model=FlowCodeTemplate.Parse(File.ReadAllText(Path.Combine(root,"portable-models/OwnPython.fpgt")));var target=FlowSourceTarget.FromTemplate("0123456789abcdef0123456789abcdef",model);Phase("Before viewer constructor");
  using(var viewer=new SourceCodeDialog(doc,null,target)){
   Phase("Viewer constructed");Profile(picker=>{Check(!picker.Generate.Enabled,"No implicit type selection");var fields=All(picker).OfType<ComboBox>().ToList();Check(fields.Count==1&&fields[0].SelectedIndex==0,"Actual input candidate shown");Phase("Before capture");Capture(picker,Path.Combine(root,"ui-fpgt/profile.png"));Phase("After capture");fields[0].SelectedIndex=1;Check(picker.Generate.Enabled,"Deliberate choice enables generation");picker.Generate.PerformClick();},()=>viewer.Show());
   Until(()=>viewer.Source!=null,"Native viewer asynchronously generates actual typed code");Check(viewer.Source.Text.Contains("int(input())")&&viewer.Save.Enabled&&viewer.Copy.Enabled,"Generated copy uses chosen type");string copied=null;viewer.ClipboardWrite=s=>copied=s;viewer.Copy.PerformClick();Check(copied==viewer.Source.Text,"Copy exports actual full model output");string first=viewer.Source.Text;
   Profile(picker=>{Check(picker.Generate.Enabled,"Current profile is offered for revision");((IButtonControl)picker.CancelButton).PerformClick();},()=>viewer.Types.PerformClick());Check(viewer.Source.Text==first&&viewer.Copy.Enabled,"Cancelled revision preserves previous valid output");
   Profile(picker=>{All(picker).OfType<ComboBox>().Single().SelectedIndex=2;picker.Generate.PerformClick();},()=>viewer.Types.PerformClick());Until(()=>viewer.Source!=null&&viewer.Source.Text.Contains("float(input())"),"Revised choice regenerates a real second output");Capture(viewer,Path.Combine(root,"ui-fpgt/source.png"));viewer.Close();
  }
  using(var viewer=new SourceCodeDialog(doc,null,target)){Profile(picker=>((IButtonControl)picker.CancelButton).PerformClick(),()=>viewer.Show());Check(viewer.Source==null&&!viewer.Save.Enabled&&!viewer.Copy.Enabled&&viewer.Types.Enabled,"Initial cancellation retains a retry without exporting stale text");viewer.Close();}
  var bad=FlowPseudocode.Decode("v=[1,2]\nSTAMPA size(v)");string errorNode=bad.Nodes.Single(n=>n.Kind==NodeKind.Process).Id;string located=null;using(var viewer=new SourceCodeDialog(bad,(f,n)=>located=n,target)){viewer.Show();Until(()=>viewer.LastError!=null,"Unsupported source gets real linked diagnostic");Check(viewer.Source==null&&!viewer.Save.Enabled&&viewer.Locate.Enabled,"Error cannot be exported and can locate its block");viewer.Locate.PerformClick();Check(located==errorNode&&!viewer.Visible,"Error navigation reaches original block");}
  var store=new FlowTemplateStore(Path.Combine(root,"ui-fpgt/store",FlowTemplateStore.NewId()));string id=FlowTemplateStore.NewId();using(var editor=new CodeTemplateEditor(store,id,new FlowTemplateDraft(model),doc)){editor.Show();Pump();Check(editor.BodyLabel.Text.Contains(".FPGT")&&!editor.BaseField.Enabled&&!editor.CaseField.Enabled&&editor.ExtensionField.ReadOnly,"Original format has explicit guided controls");Check(editor.BodyField.Text==model.Body,"Complete raw text reaches native editor");editor.NameField.Text="Modello importato";editor.SaveButton.PerformClick();Until(()=>!editor.Visible,"Actual raw model save completes");Check(editor.Saved.Definition.Fpgt!=null&&store.Load(id).Draft==null,"Real saved model and matching draft cleanup");}
  string fingerprint=store.Load(id).Fingerprint;string incomplete=model.Body.Replace("[Language]","[Language");using(var editor=new CodeTemplateEditor(store,id,null,doc)){editor.Show();editor.BodyField.Text=incomplete;editor.Close();Until(()=>!editor.Visible,"Closing unfinished raw format flushes a real draft");Check(FlowTemplateDraft.Decode(store.Load(id).Draft).Body==incomplete&&store.Load(id).Fingerprint==fingerprint,"Invalid fpgt edits remain separate from saved revision");}
  using(var editor=new CodeTemplateEditor(store,id,null,doc)){editor.Show();Pump();Check(editor.BodyField.Text==incomplete,"Incomplete original-format draft reopens intact");editor.BodyField.Text=model.Body;editor.SaveButton.PerformClick();Until(()=>!editor.Visible,"Repairing the draft produces a real valid save");Check(store.Load(id).Draft==null,"Successful repair clears only its matching draft");}
  using(var library=new CodeTemplateLibrary(store,doc)){library.Show();Until(()=>library.UseButton.Enabled&&library.Results.Enabled,"Saved raw model is usable in real library");string filename=null;library.ExportPathPicker=name=>{filename=name;return Path.Combine(root,"ui-fpgt/export.fpgt");};library.ExportButton.PerformClick();try{Until(()=>File.Exists(Path.Combine(root,"ui-fpgt/export.fpgt"))&&library.ExportButton.Enabled,"Actual library exports fpgt");}catch{Phase("Export filename="+filename+" error="+library.LastError);throw;}Check(filename=="Modello.fpgt"&&FlowCodeTemplate.Parse(FlowTemplateStore.ReadImport(Path.Combine(root,"ui-fpgt/export.fpgt"))).Fpgt!=null,"Picker filename and contents retain official format");library.Close();}
  string importPath=Path.Combine(root,"ui-fpgt/utf16.fpgt");File.WriteAllText(importPath,model.Body,new UnicodeEncoding(false,true,true));byte[] originalImport=File.ReadAllBytes(importPath);using(var library=new CodeTemplateLibrary(store,doc)){library.Show();Until(()=>library.ImportButton.Enabled&&library.Results.Items.Count==1,"Library initial load completes before import");Exception failure=null;using(var timer=new System.Windows.Forms.Timer{Interval=25}){timer.Tick+=delegate{var editor=Application.OpenForms.OfType<CodeTemplateEditor>().FirstOrDefault(f=>f.Visible);if(editor==null)return;timer.Stop();try{Check(editor.BodyField.Text==model.Body&&editor.BodyLabel.Text.Contains(".FPGT"),"Native UTF16 import opens the actual original-format review");Check(store.Entries().Count==1,"Import requires explicit review/save before adding a model");editor.SaveButton.PerformClick();}catch(Exception error){failure=error;editor.Dispose();}};timer.Start();library.ImportPathPicker=()=>importPath;library.ImportButton.PerformClick();Until(()=>store.Entries().Count==2&&library.Results.Enabled,"Reviewed fpgt import commits a distinct durable model");timer.Stop();if(failure!=null)throw failure;}Check(originalImport.SequenceEqual(File.ReadAllBytes(importPath)),"Import never rewrites the selected UTF16 file");library.Close();}
  var local=FlowPseudocode.Decode("LEGGI x\nSTAMPA x+1");using(var window=new Form{Size=new Size(700,600)}){var preview=new PseudocodePreview(()=>DiagramIO.Clone(local));window.Controls.Add(preview);window.Show();preview.SetTarget(target);Until(()=>preview.Types.Visible,"Live sidebar exposes type choice");Profile(picker=>{All(picker).OfType<ComboBox>().Single().SelectedIndex=1;picker.Generate.PerformClick();},()=>preview.Types.PerformClick());Until(()=>preview.PythonCode.Source!=null,"Live sidebar renders typed output");Check(preview.PythonCode.Source.Text.Contains("int(input())"),"Live source uses actual chosen profile");
   local.Nodes.Single(n=>n.Kind==NodeKind.Output).Text="x+2";preview.RefreshNow();System.Threading.Thread.Sleep(150);local.Nodes.Single(n=>n.Kind==NodeKind.Output).Text="(";preview.RefreshNow();Pump(400);Check(preview.PythonCode.Source==null&&!preview.Types.Visible,"Late source completion cannot overwrite a newer invalid diagram");local.Nodes.Single(n=>n.Kind==NodeKind.Output).Text="x+3";preview.RefreshNow();Until(()=>preview.PythonCode.Source!=null,"Live sidebar recovers after fixing diagram");window.Close();}
  Check(before==Convert.ToBase64String(DiagramIO.EncodeDocument(doc)),"All native workflows preserve the original input diagram");Console.WriteLine("FPGT_INTEGRATION_UI_PC PASS checks="+checks);return 0;
 }catch(Exception error){Console.WriteLine(error);foreach(Form form in Application.OpenForms.Cast<Form>().ToList())form.Dispose();return 1;}}
}
